#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/mem_blocks.h>

#define BLOCK_SIZE 32
#define NUM_BLOCKS 4

/*
 * The original K_MEM_BLOCKS_DEFINE might have used an alignment value
 * that is not a power of 2 (e.g., 3 or 5). This can lead to incorrect
 * memory block initialization and subsequent runtime errors when
 * attempting to use the memory blocks, such as getting or freeing blocks,
 * or retrieving statistics.
 *
 * The fix is to ensure the alignment parameter is a valid power of 2.
 * Using '8' provides a common and safe alignment for many architectures.
 * Alternatively, '0' could be used to default to K_MEM_BLOCK_ALIGN_DEFAULT
 * (which is sizeof(void *)).
 */
K_MEM_BLOCKS_DEFINE(test_mem_blocks, BLOCK_SIZE, NUM_BLOCKS, 8);

static void test_mem_blocks_runtime_stats(void)
{
    struct k_mem_blocks_stats stats;
    int status;
    void *block_ptr[NUM_BLOCKS];

    /* Test initial stats */
    status = k_mem_blocks_stats_get(&test_mem_blocks, &stats);
    zassert_equal(status, 0, "Failed to get initial stats (status: %d)", status);
    zassert_equal(stats.num_blocks_used, 0, "Initial blocks used not 0");
    zassert_equal(stats.num_blocks_free, NUM_BLOCKS, "Initial blocks free not %d", NUM_BLOCKS);
    zassert_equal(stats.max_blocks_used, 0, "Initial max blocks used not 0");

    /* Allocate all blocks */
    for (int i = 0; i < NUM_BLOCKS; i++) {
        status = k_mem_blocks_get(&test_mem_blocks, &block_ptr[i], K_NO_WAIT);
        zassert_equal(status, 0, "Failed to get block %d (status: %d)", i, status);
        zassert_not_null(block_ptr[i], "Block %d is NULL", i);
    }

    /* Test stats after allocating all blocks */
    status = k_mem_blocks_stats_get(&test_mem_blocks, &stats);
    zassert_equal(status, 0, "Failed to get stats after allocation (status: %d)", status);
    zassert_equal(stats.num_blocks_used, NUM_BLOCKS, "Blocks used not %d after full allocation", NUM_BLOCKS);
    zassert_equal(stats.num_blocks_free, 0, "Blocks free not 0 after full allocation");
    zassert_equal(stats.max_blocks_used, NUM_BLOCKS, "Max blocks used not %d after full allocation", NUM_BLOCKS);

    /* Try to allocate one more (should fail) */
    void *extra_block;
    status = k_mem_blocks_get(&test_mem_blocks, &extra_block, K_NO_WAIT);
    zassert_not_equal(status, 0, "Unexpectedly got an extra block (status: %d)", status);
    zassert_is_null(extra_block, "Extra block pointer not NULL");

    /* Free some blocks */
    for (int i = 0; i < NUM_BLOCKS / 2; i++) {
        status = k_mem_blocks_free(&test_mem_blocks, block_ptr[i]);
        zassert_equal(status, 0, "Failed to free block %d (status: %d)", i, status);
    }

    /* Test stats after freeing some blocks */
    status = k_mem_blocks_stats_get(&test_mem_blocks, &stats);
    zassert_equal(status, 0, "Failed to get stats after partial free (status: %d)", status);
    zassert_equal(stats.num_blocks_used, NUM_BLOCKS / 2, "Blocks used not %d after partial free", NUM_BLOCKS / 2);
    zassert_equal(stats.num_blocks_free, NUM_BLOCKS / 2, "Blocks free not %d after partial free", NUM_BLOCKS / 2);
    zassert_equal(stats.max_blocks_used, NUM_BLOCKS, "Max blocks used changed after partial free");

    /* Free remaining blocks */
    for (int i = NUM_BLOCKS / 2; i < NUM_BLOCKS; i++) {
        status = k_mem_blocks_free(&test_mem_blocks, block_ptr[i]);
        zassert_equal(status, 0, "Failed to free block %d (status: %d)", i, status);
    }

    /* Test final stats */
    status = k_mem_blocks_stats_get(&test_mem_blocks, &stats);
    zassert_equal(status, 0, "Failed to get final stats (status: %d)", status);
    zassert_equal(stats.num_blocks_used, 0, "Final blocks used not 0");
    zassert_equal(stats.num_blocks_free, NUM_BLOCKS, "Final blocks free not %d", NUM_BLOCKS);
    zassert_equal(stats.max_blocks_used, NUM_BLOCKS, "Max blocks used changed after full free");
}

ZTEST_SUITE(lib_mem_blocks_stats_test, NULL, NULL, NULL, NULL, NULL);

ZTEST(lib_mem_blocks_stats_test, test_mem_blocks_runtime_stats)
{
    test_mem_blocks_runtime_stats();
}
